function canReachLast(hops: number[]): boolean {
  const n = hops.length;
  const reach = new Array(n).fill(false);
  reach[0] = true;
  for (let i = 0; i < n; i++) {
    if (!reach[i]) continue;
    for (let j = i + 1; j <= Math.min(n - 1, i + hops[i]); j++) reach[j] = true;
  }
  return reach[n - 1];
}

