function canReachLast(hops: number[]): boolean {
  let far = 0;
  for (let i = 0; i < hops.length; i++) {
    if (i > far) return false;
    far = Math.max(far, i + hops[i]);
    if (far >= hops.length - 1) return true;
  }
  return true;
}

